51:   // Auto-expand the textarea up to a comfortable ceiling.
52:   useEffect(() => {
53:     const el = areaRef.current;
54:     if (!el) return;
55:     el.style.height = '0px';
56:     el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
57:   }, [draft]);
