214:                   Listening...
215:                 </div>
216:               ) : (
217:                 <label htmlFor="vigil-composer" className="sr-only">
218:                   Message Vigil
219:                 </label>
220:               )}
221:               {recording ? null : (
222:                 <textarea
223:                   id="vigil-composer"
224:                   ref={areaRef}
225:                   rows={1}
226:                   value={draft}
227:                   onChange={(e) => setDraft(e.target.value)}
228:                   onKeyDown={(e) => {
