233:                   }}
234:                   placeholder="Ask Vigil anything or assign a task..."
235:                   disabled={disabled}
236:                   className="max-h-[160px] w-full resize-none rounded-[12px] bg-[color-mix(in_srgb,var(--text)_10%,transparent)] px-3 py-[10px] text-[15px] leading-relaxed text-[var(--text)] outline-none placeholder:text-[var(--text-muted)] disabled:opacity-60"
237:                 />
238:               )}
239:             </div>
240: 
241:             <button
242:               type="button"
243:               aria-label={recording ? 'Stop recording' : 'Record voice'}
