const areaRef = useRef<HTMLTextAreaElement>(null);
const fileRef = useRef<HTMLInputElement>(null);
const streamRef = useRef<MediaStream | null>(null);
const ctxRef = useRef<AudioContext | null>(null);
const mediaRecorderRef = useRef<MediaRecorder | null>(null);
const chunksRef = useRef<Blob[]>([]);

useEffect(() => {
  if (!seed) return;
  setDraft(seed);
  onSeedConsumed?.();
  areaRef.current?.focus();
}, [seed, onSeedConsumed]);

// Auto-expand the textarea up to a comfortable ceiling.
useEffect(() => {
  const el = areaRef.current;
  if (!el) return;
  el.style.height = '0px';
  el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
}, [draft]);

// Microphone hardware must never outlive the component.
useEffect(() => {
  return () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      try {
        mediaRecorderRef.current.stop();
      } catch {
        // cleanup
      }
    }
    streamRef.current?.getTracks().forEach((track) => track.stop());
    void ctxRef.current?.close();
  };
}, []);

const releaseCapture = () => {
  streamRef.current?.getTracks().forEach((track) => track.stop());
  streamRef.current = null;
  void ctxRef.current?.close();
  ctxRef.current = null;
  setAnalyser(null);
};

const transcribeAudio = async (audioBlob: Blob) => {
  try {
    setNotice('Transcribing audio...');
    const formData = new FormData();
    formData.append('file', audioBlob, 'recording.webm');

    const headers: Record<string, string> = {};
    const token = getBearerToken();
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const res = await fetch('/api/v1/voice/transcribe', {
      method: 'POST',
      headers,
      body: formData,
    });

    if (!res.ok) {
      throw new Error(`Transcription failed (${res.status})`);
    }

    const data = (await res.json()) as { text?: string };
    if (data && data.text) {
      setDraft((prev) => (prev ? `${prev.trim()} ${data.text}` : data.text));
      setNotice(null);
      areaRef.current?.focus();
    } else {
      setNotice('No speech recognized.');
    }
  } catch {
    setNotice('Voice transcription failed. You can type your message instead.');
  }
};

const startCapture = async () => {
  if (!navigator.mediaDevices?.getUserMedia) {
    setNotice('This browser exposes no microphone to the page.');
    return;
  }
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    streamRef.current = stream;

    const ctx = new AudioContext();
    ctxRef.current = ctx;
    const source = ctx.createMediaStreamSource(stream);
    const node = ctx.createAnalyser();
    node.fftSize = 1024;
    node.smoothingTimeConstant = 0.65;
    source.connect(node);

    setAnalyser(node);

    chunksRef.current = [];
    if (typeof MediaRecorder !== 'undefined') {
      const recorder = new MediaRecorder(stream);
      recorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };
      recorder.start(100);
      mediaRecorderRef.current = recorder;
    }

    setRecording(true);
    setNotice(null);
  } catch {
    setNotice('Microphone permission was declined, so nothing is being captured.');
  }
};

const stopCapture = () => {
  setRecording(false);
  const recorder = mediaRecorderRef.current;
  if (recorder && recorder.state !== 'inactive') {
    recorder.onstop = () => {
      const chunks = chunksRef.current;
      if (chunks.length > 0) {
        const audioBlob = new Blob(chunks, { type: 'audio/webm' });
        void transcribeAudio(audioBlob);
      }
    };
    try {
      recorder.stop();
    } catch {
      // Fallback
    }
  }
  mediaRecorderRef.current = null;
  releaseCapture();
};

