setVaultSecret(body) {
  const masked = body.value.length > 8 ? `${body.value.slice(0, 3)}****${body.value.slice(-4)}` : '****';
  const now = new Date().toISOString();
  const existingIndex = mockVaultSecrets.findIndex((s) => s.key_name === body.key);
  if (existingIndex >= 0) {
    mockVaultSecrets[existingIndex] = {
      ...mockVaultSecrets[existingIndex],
      masked_value: masked,
      updated_at: now,
    };
  } else {
    mockVaultSecrets.push({
      key_name: body.key,
      masked_value: masked,
      created_at: now,
      updated_at: now,
    });
  }
  return later({ ok: true, key: body.key });
},

